HOST = "<<BASE>>/host"
DUMPCAT = "filegroup(name = 'g', srcs = glob(%s))\ngenrule(name = 'dump', srcs = [':g'], outs = ['dump.txt'], cmd = 'for f in $(SRCS); do echo $$f; done > $@')\ngenrule(name = 'cat', srcs = [':g'], outs = ['cat.txt'], cmd = 'cat $(SRCS) > $@')\n"

def _gen(ctx):
    k = ctx.attr.kind
    ctx.file("own.txt", "own\n")
    ctx.file("id.marker", "id=" + ctx.attr.id + "\n")
    if k == "dir":
        ctx.symlink(HOST + "/files", "d")
        pat = "['**/*.txt']"
    elif k == "withbuild":
        ctx.symlink(HOST + "/withbuild", "wb")
        pat = "['**/*.txt']"
    elif k == "dangling":
        ctx.symlink(HOST + "/nothere.txt", "x.txt")
        pat = "['*.txt']"
    elif k == "cycle":
        ctx.symlink(HOST + "/cyc", "hc")
        pat = "['hc/**']"
    elif k == "host_inf":
        ctx.symlink(HOST + "/up", "hu")
        pat = "['hu/**']"
    elif k == "file":
        ctx.symlink(HOST + "/h.txt", "h.txt")
        pat = "['*.txt']"
    elif k == "path_obj":
        ctx.symlink(ctx.path(HOST + "/files"), "d")
        pat = "['d/**']"
    elif k == "host_chain":
        ctx.symlink(HOST + "/chain", "d")
        pat = "['d/**']"
    elif k == "host_fifo":
        ctx.symlink(HOST + "/fifo.txt", "f.txt")
        pat = "['*.txt']"
    ctx.file("BUILD.bazel", DUMPCAT % pat)

gen = repository_rule(_gen, attrs = {"kind": attr.string(), "id": attr.string()})

def _ext(mctx):
    for mod in mctx.modules:
        for t in mod.tags.g:
            gen(name = t.name, kind = t.kind, id = t.name)

ext = module_extension(_ext, tag_classes = {"g": tag_class(attrs = {"name": attr.string(), "kind": attr.string()})})

