load(":lib.bzl", "describe")
load(":defs.bzl", "lk")

def _ext(mctx):
    for mod in mctx.modules:
        for t in mod.tags.t:
            p = t.platforms
            m = t.mode
            if m == "pass":
                v = p
            elif m == "mixed":
                v = dict(p)
                v[Label("//:x")] = "lx"
                v["//:y"] = "sy"
            elif m == "strs":
                v = {"//:s": "s", "@plat//cpu:x86_64": "p", ":r": "r"}
            elif m == "foreign":
                v = {Label("@lib//:t"): "t", Label("@@platforms+//cpu:arm64"): "a"}
            elif m == "dupmix":
                v = {Label("//:a"): "x", "//:a": "y"}
            elif m == "duplabels":
                v = {Label("//:a"): "x", Label("@@//:a"): "y"}
            elif m == "badvalue":
                v = {Label("//:a"): 1}
            elif m == "mutate_tag":
                p[Label("//:z")] = "z"
                v = p
            lk(name = t.name, platforms = v, text = mod.name + "|" + str(mod.is_root) + "|" + describe(p) + "|" + repr(t.skd))

ext = module_extension(_ext, tag_classes = {"t": tag_class(attrs = {
    "name": attr.string(),
    "platforms": attr.label_keyed_string_dict(),
    "mode": attr.string(default = "pass"),
    "skd": attr.string_keyed_label_dict(),
})})

