def describe(d):
    return json.encode([[type(k), str(k), v] for k, v in d.items()])

def _lr(ctx):
    ctx.file("BUILD.bazel", "exports_files(['data'])\n")
    ctx.file("data", ctx.attr.text + "\n" + describe(ctx.attr.platforms) + "\n", executable = False)

lr = repository_rule(_lr, attrs = {"platforms": attr.label_keyed_string_dict(), "text": attr.string()})

def _ext(mctx):
    for mod in mctx.modules:
        for t in mod.tags.t:
            lr(name = t.name, platforms = t.platforms, text = mod.name + "|" + describe(t.platforms))

ext = module_extension(_ext, tag_classes = {"t": tag_class(attrs = {"name": attr.string(), "platforms": attr.label_keyed_string_dict()})})

